def transform_corrected(grid):
    if not grid or not grid[0]:
        return grid

    h, w = len(grid), len(grid[0])

    active_row = -1
    for row in range(h):
        for col in range(w):
            if grid[row][col] > 1:
                active_row = row
                break
        if active_row != -1:
            break

    if active_row == -1:
        return grid

    count = sum(1 for col in range(w) if grid[active_row][col] > 1)
    only = count == 1

    out = [[0] * w for _ in range(h)]

    pattern_row = active_row - 1 if not only else active_row

    for col in range(w):
        out[pattern_row][col] = grid[active_row][col]

    for v, c in [(grid[active_row][col], col) for col in range(w) if grid[active_row][col] > 1]:
        if only:
            if v == 2:
                top = active_row - 4
                bottom = active_row
            else:  # v == 8
