                bottom = active_row
        else:  # not only
            if v == 8:
                top = active_row - 1
                bottom = active_row - 1
            else:  # v == 2
                top = active_row - 4
                bottom = active_row - 1

        if top >= 0:
            start_row = 0 if top < 0 else top

